652:         /// <summary>
653:         /// Prepares the action execution context for use.
654:         /// </summary>
655:         public static Action<ActionExecutionContext> PrepareContext = context =>
656:         {
657:             Log.Info("PrepareContext");
658:             SetMethodBinding(context);
659:             Log.Info("PrepareContext Context is  {0}", context.View);
660:             Log.Info("PrepareContext method is null {0}", context.Method == null);
661:             Log.Info("PrepareContext target is null {0}", context.Target == null);
662:             if (context.Target == null || context.Method == null)
663:             {
664:                 return;
665:             }
666:             var possibleGuardNames = BuildPossibleGuardNames(context.Method).ToList();
667:             Log.Info($"PrepareContext {possibleGuardNames.Count}");
668:             foreach (var methodName in possibleGuardNames)
669:             {
670:                 Log.Info($"PrepareContext {methodName}");
671:             }
672:             var guard = TryFindGuardMethod(context, possibleGuardNames);
673: 
674:             if (guard == null)
675:             {
676:                 Log.Info("Guard not found");
677:                 var inpc = context.Target as INotifyPropertyChanged;
678:                 if (inpc == null)
679:                     return;
680: 
681:                 var targetType = context.Target.GetType();
682:                 string matchingGuardName = null;
683:                 foreach (string possibleGuardName in possibleGuardNames)
684:                 {
685:                     matchingGuardName = possibleGuardName;
686:                     guard = GetMethodInfo(targetType, "get_" + matchingGuardName);
687:                     if (guard != null)
688:                         break;
689:                 }
690: 
691:                 if (guard == null)
692:                     return;
693:                 Log.Info("Found guard 2 try");
694:                 PropertyChangedEventHandler handler = null;
695:                 handler = (s, e) =>
696:                 {
697:                     if (string.IsNullOrEmpty(e.PropertyName) || e.PropertyName == matchingGuardName)
698:                     {
699:                         Log.Info($"UpdateAvailablilty  {e.PropertyName}");
700:                         Caliburn.Micro.Execute.OnUIThread(() =>
701:                         {
702:                             var message = context.Message;
703:                             if (message == null)
704:                             {
705:                                 inpc.PropertyChanged -= handler;
706:                                 return;
707:                             }
708:                             message.UpdateAvailability();
709:                         });
710:                     }
711:                 };
712: 
713:                 inpc.PropertyChanged += handler;
714:                 context.Disposing += delegate
715:                 { inpc.PropertyChanged -= handler; };
716:                 context.Message.Detaching += delegate
717:                 { inpc.PropertyChanged -= handler; };
718:             }
719:             Log.Info("guard create method {0}", guard.Name);
720:             context.CanExecute = () => (bool)guard.Invoke(
721:                 context.Target,
722:                 MessageBinder.DetermineParameters(context, guard.GetParameters()));
