725:         /// <summary>
726:         /// Try to find a candidate for guard function, having: 
727:         ///    - a name matching any of <paramref name="possibleGuardNames"/>
728:         ///    - no generic parameters
729:         ///    - a bool return type
730:         ///    - no parameters or a set of parameters corresponding to the action method
731:         /// </summary>
732:         /// <param name="context">The execution context</param>
733:         /// <param name="possibleGuardNames">Method names to look for.</param>
734:         ///<returns>A MethodInfo, if found; null otherwise</returns>
735:         static MethodInfo TryFindGuardMethod(ActionExecutionContext context, IEnumerable<string> possibleGuardNames)
736:         {
737:             var targetType = context.Target.GetType();
738:             MethodInfo guard = null;
739:             foreach (string possibleGuardName in possibleGuardNames)
740:             {
741:                 guard = GetMethodInfo(targetType, possibleGuardName);
742:                 if (guard != null)
743:                     break;
744:             }
745: 
746:             if (guard == null)
747:                 return null;
748:             if (guard.ContainsGenericParameters)
749:                 return null;
750:             if (!typeof(bool).Equals(guard.ReturnType))
751:                 return null;
752: 
753:             var guardPars = guard.GetParameters();
754:             var actionPars = context.Method.GetParameters();
755:             if (guardPars.Length == 0)
756:                 return guard;
757:             if (guardPars.Length != actionPars.Length)
758:                 return null;
759: 
760:             var comparisons = guardPars.Zip(
761:                 context.Method.GetParameters(),
762:                 (x, y) => x.ParameterType == y.ParameterType
763:                 );
764: 
765:             if (comparisons.Any(x => !x))
766:             {
767:                 return null;
768:             }
769:             Log.Info($"TryFindGuardMethod {guard.Name}");
770:             return guard;
771:         }
