773:         /// <summary>
774:         /// Returns the list of possible names of guard methods / properties for the given method.
775:         /// </summary>
776:         public static Func<MethodInfo, IEnumerable<string>> BuildPossibleGuardNames = method =>
777:         {
778: 
779:             var guardNames = new List<string>();
780: 
781:             const string GuardPrefix = "Can";
782: 
783:             var methodName = method.Name;
784: 
785:             guardNames.Add(GuardPrefix + methodName);
786: 
787:             const string AsyncMethodSuffix = "Async";
788: 
789:             if (methodName.EndsWith(AsyncMethodSuffix, StringComparison.OrdinalIgnoreCase))
790:             {
791:                 guardNames.Add(GuardPrefix + methodName.Substring(0, methodName.Length - AsyncMethodSuffix.Length));
792:             }
793: 
794:             return guardNames;
795:         };
796: 
797:         static MethodInfo GetMethodInfo(Type t, string methodName)
798:         {
799: #if WINDOWS_UWP
800:             return t.GetRuntimeMethods().SingleOrDefault(m => m.Name == methodName);
801: #else
802:             return t.GetMethod(methodName);
803: #endif
804:         }
805:     }
